import { sqliteTable, text, integer, real, blob, uniqueIndex as sqliteUniqueIndex, type AnySQLiteColumn } from 'drizzle-orm/sqlite-core';
import { mysqlTable, varchar, int, decimal, datetime, boolean as mysqlBoolean, text as mysqlText, customType, mysqlEnum, uniqueIndex as mysqlUniqueIndex, type AnyMySqlColumn } from 'drizzle-orm/mysql-core';
import { relations, sql } from 'drizzle-orm';

// Custom type for MySQL LONGBLOB (for storing large binary files)
const longblob = customType<{ data: Buffer; driverData: Buffer }>({
  dataType() {
    return 'LONGBLOB';
  },
  toDriver(value: Buffer): Buffer {
    return value;
  },
  fromDriver(value: Buffer): Buffer {
    return Buffer.isBuffer(value) ? value : Buffer.from(value);
  },
});

// ============================================
// SQLite Schema (for unit testing)
// ============================================

// Users table
export const sqliteUsers = sqliteTable('users', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  email: text('email').notNull().unique(),
  password: text('password').notNull(),
  name: text('name').notNull(),
  role: text('role').notNull().default('user'), // admin, manager, user, qc, production
  department: text('department'),
  isActive: integer('is_active', { mode: 'boolean' }).notNull().default(true),
  createdAt: text('created_at').notNull().default('CURRENT_TIMESTAMP'),
  updatedAt: text('updated_at').notNull().default('CURRENT_TIMESTAMP'),
});

// Audit Trail
export const sqliteAuditTrail = sqliteTable('audit_trail', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  userId: integer('user_id').references(() => sqliteUsers.id),
  action: text('action').notNull(), // CREATE, UPDATE, DELETE, LOGIN, LOGOUT
  tableName: text('table_name'),
  recordId: integer('record_id'),
  oldValue: text('old_value'),
  newValue: text('new_value'),
  ipAddress: text('ip_address'),
  createdAt: text('created_at').notNull().default('CURRENT_TIMESTAMP'),
});

// Item Categories (หมวดหมู่สินค้า)
export const sqliteItemCategories = sqliteTable('item_categories', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  code: text('code').notNull().unique(),
  nameTh: text('name_th').notNull(),
  nameEn: text('name_en'),
  description: text('description'),
  sortOrder: integer('sort_order').notNull().default(0),
  isActive: integer('is_active', { mode: 'boolean' }).notNull().default(true),
  createdAt: text('created_at').notNull().default('CURRENT_TIMESTAMP'),
  updatedAt: text('updated_at').notNull().default('CURRENT_TIMESTAMP'),
});

// Lot Number Patterns — per-factory configurable lot number format.
// Two scope rows: 'system' (internal lot generated by the system) and
// 'vendor' (validation/hint rules for vendor-supplied lot numbers).
export const sqliteLotPatterns = sqliteTable('lot_patterns', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  patternType: text('pattern_type').notNull().unique(), // 'system' | 'vendor'
  // System-lot fields
  prefix: text('prefix').notNull().default('LOT'),
  separator: text('separator').notNull().default('-'),
  includeDate: integer('include_date', { mode: 'boolean' }).notNull().default(true),
  dateFormat: text('date_format').notNull().default('YYYYMMDD'), // YYYYMMDD | YYMMDD | BE-YYMMDD | BE-YYYYMMDD | YYYY-MM-DD
  sequenceType: text('sequence_type').notNull().default('random'), // 'random' | 'sequential'
  sequenceLength: integer('sequence_length').notNull().default(3),
  sequenceStart: integer('sequence_start').notNull().default(1),
  // Vendor-lot fields
  regexPattern: text('regex_pattern'), // optional regex for validation
  hintTh: text('hint_th'), // placeholder TH
  hintEn: text('hint_en'), // placeholder EN
  isActive: integer('is_active', { mode: 'boolean' }).notNull().default(true),
  notes: text('notes'),
  updatedBy: integer('updated_by').references(() => sqliteUsers.id),
  createdAt: text('created_at').notNull().default('CURRENT_TIMESTAMP'),
  updatedAt: text('updated_at').notNull().default('CURRENT_TIMESTAMP'),
});

// Item Code Patterns — per-factory configurable code format per item type.
// Replaces hard-coded PREFIX_MAP in /api/items/next-code so each tenant can
// define their own prefix/separator/padding/year format.
export const sqliteItemCodePatterns = sqliteTable('item_code_patterns', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  itemType: text('item_type').notNull().unique(), // raw_material | packaging | wip | finished_goods | extract | consumable
  prefix: text('prefix').notNull(), // e.g. 'RM', 'ม.', 'วต'
  separator: text('separator').notNull().default('-'), // '-' | '_' | '/' | '' | '.'
  padding: integer('padding').notNull().default(4), // sequence digit width
  includeYear: integer('include_year', { mode: 'boolean' }).notNull().default(false),
  yearFormat: text('year_format').notNull().default('YYYY'), // 'YY' | 'YYYY' | 'BE-YY' | 'BE-YYYY'
  yearPosition: text('year_position').notNull().default('after_prefix'), // 'after_prefix' | 'before_seq'
  sequenceStart: integer('sequence_start').notNull().default(1),
  isActive: integer('is_active', { mode: 'boolean' }).notNull().default(true),
  notes: text('notes'),
  updatedBy: integer('updated_by').references(() => sqliteUsers.id),
  createdAt: text('created_at').notNull().default('CURRENT_TIMESTAMP'),
  updatedAt: text('updated_at').notNull().default('CURRENT_TIMESTAMP'),
});

// Item Units (หน่วยวัดสินค้า)
export const sqliteItemUnits = sqliteTable('item_units', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  code: text('code').notNull().unique(),
  nameTh: text('name_th').notNull(),
  nameEn: text('name_en'),
  symbol: text('symbol'), // e.g., kg, g, L, pcs
  description: text('description'),
  sortOrder: integer('sort_order').notNull().default(0),
  isActive: integer('is_active', { mode: 'boolean' }).notNull().default(true),
  createdAt: text('created_at').notNull().default('CURRENT_TIMESTAMP'),
  updatedAt: text('updated_at').notNull().default('CURRENT_TIMESTAMP'),
});

// Item Master (วัตถุดิบ/สินค้า)
export const sqliteItems = sqliteTable('items', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  code: text('code').notNull().unique(),
  nameTh: text('name_th').notNull(),
  nameEn: text('name_en'),
  type: text('type').notNull(), // raw_material, packaging, wip, finished_goods, consumable
  category: text('category'),
  primaryUnit: text('primary_unit').notNull(),
  secondaryUnit: text('secondary_unit'),
  conversionRate: real('conversion_rate'),
  // 3-level unit conversion (PU → SU → WU)
  // Why: pharma items are stored in PU (กล่อง) but produced/issued by SU (แคปซูล)
  // and consumed by weight (กรัม). Weighed-issuance flow needs WU → SU back-conversion.
  weightUnit: text('weight_unit'), // WU label e.g. 'g'
  secondaryToWeightRate: real('secondary_to_weight_rate'), // Ratio2: 1 SU = ? WU
  weightTrackingEnabled: integer('weight_tracking_enabled', { mode: 'boolean' }).notNull().default(false),
  shelfLifeDays: integer('shelf_life_days'),
  storageCondition: text('storage_condition'),
  minStock: real('min_stock').default(0),
  maxStock: real('max_stock'),
  reorderPoint: real('reorder_point'),
  onHand: real('on_hand').notNull().default(0), // Cached on-hand quantity from released lots
  onHandCost: real('on_hand_cost').notNull().default(0), // Cached total cost of on-hand inventory
  quarantineQty: real('quarantine_qty').notNull().default(0), // Cached quantity in quarantine/under_test status
  isLotControlled: integer('is_lot_controlled', { mode: 'boolean' }).notNull().default(true),
  isFEFO: integer('is_fefo', { mode: 'boolean' }).notNull().default(true),
  isActive: integer('is_active', { mode: 'boolean' }).notNull().default(true),
  // BOM Confidentiality Protection fields (014-unit-cost)
  confidentialityLevel: text('confidentiality_level').$type<'public' | 'internal' | 'confidential'>().notNull().default('public'),
  defaultConfidential: integer('default_confidential', { mode: 'boolean' }).notNull().default(false),
  // VMI Standard Codes - items need EITHER tppCode OR ttmtCode for VMI sync
  tppCode: text('tpp_code'), // Thai Pharmaceutical Product code (13 digits)
  tppName: text('tpp_name'), // TPP product name from VMI Portal
  ttmtCode: text('ttmt_code'), // Thai Traditional Medicine Terminology (A + 8 digits)
  ttmtName: text('ttmt_name'), // TTMT product name (FSN) from VMI Portal
  drugCode24: text('drug_code_24'), // 24-digit drug registration code
  // VMI Vendor Sync fields (008-vmi-vendor-sync)
  vmiSyncEnabled: integer('vmi_sync_enabled', { mode: 'boolean' }).notNull().default(false),
  lastVmiSyncAt: text('last_vmi_sync_at'),
  // Phase 2: Strength/potency for finished goods (FR-059)
  strength: text('strength'), // legacy free-text (kept for back-compat / display)
  // Structured strength so BOM + WO can compute (value + selectable unit).
  strengthValue: real('strength_value'),
  strengthUnit: text('strength_unit'), // mg, g, mcg, IU, %, mg/capsule, ...
  // Net weight of ONE sub-unit of this material in mg — a fixed master-data
  // property (e.g. an empty size-0 capsule shell). The WO yield step adds
  // capsuleCount × unitWeightMg to the powder weight for the final filled weight.
  unitWeightMg: real('unit_weight_mg'),
  gRegNumber: text('g_reg_number'), // เลขที่ทะเบียน G (drug registration number)
  // Unit Cost Calculation fields (014-unit-cost)
  currentWAC: real('current_wac'), // Current weighted average cost
  lastPurchaseCost: real('last_purchase_cost'), // From most recent PO receipt
  lastPurchaseDate: text('last_purchase_date'), // Date of last purchase
  lastPurchasePoId: integer('last_purchase_po_id'), // FK to purchase_orders (no Drizzle ref to avoid circular)
  lastProductionCost: real('last_production_cost'), // From most recent completed WO
  lastProductionDate: text('last_production_date'), // Date of last production
  lastProductionWoId: integer('last_production_wo_id'), // FK to work_orders (no Drizzle ref to avoid circular)
  sgaAllocationRate: real('sga_allocation_rate').default(0), // SG&A % for full cost
  standardCost: real('standard_cost'), // Standard cost for variance analysis
  createdAt: text('created_at').notNull().default('CURRENT_TIMESTAMP'),
  updatedAt: text('updated_at').notNull().default('CURRENT_TIMESTAMP'),
});

// Herbal Attributes (คุณลักษณะเฉพาะสมุนไพร)
export const sqliteHerbalAttributes = sqliteTable('herbal_attributes', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  itemId: integer('item_id').notNull().references(() => sqliteItems.id),
  botanicalName: text('botanical_name'), // ชื่อพฤกษศาสตร์
  partUsed: text('part_used'), // ใบ/ราก/เปลือก
  originCountry: text('origin_country'),
  originProvince: text('origin_province'),
  harvestDate: text('harvest_date'),
  dryingMethod: text('drying_method'),
  createdAt: text('created_at').notNull().default('CURRENT_TIMESTAMP'),
  updatedAt: text('updated_at').notNull().default('CURRENT_TIMESTAMP'),
});

// Item Images (รูปภาพสินค้า)
export const sqliteItemImages = sqliteTable('item_images', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  itemId: integer('item_id').notNull().references(() => sqliteItems.id),
  fileName: text('file_name').notNull(), // Original file name
  fileSize: integer('file_size').notNull(), // File size in bytes
  mimeType: text('mime_type').notNull(), // e.g., image/jpeg, image/png
  imageData: blob('image_data', { mode: 'buffer' }).notNull(), // Binary image data
  thumbnailData: blob('thumbnail_data', { mode: 'buffer' }), // Thumbnail binary data
  isPrimary: integer('is_primary', { mode: 'boolean' }).notNull().default(false), // Primary/main image
  sortOrder: integer('sort_order').notNull().default(0),
  description: text('description'), // Optional description/caption
  uploadedBy: integer('uploaded_by').references(() => sqliteUsers.id),
  createdAt: text('created_at').notNull().default('CURRENT_TIMESTAMP'),
});

// Vendors (ผู้ขาย)
export const sqliteVendors = sqliteTable('vendors', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  code: text('code').notNull().unique(),
  name: text('name').notNull(),
  contactPerson: text('contact_person'),
  phone: text('phone'),
  email: text('email'),
  address: text('address'),
  taxId: text('tax_id'),
  isApproved: integer('is_approved', { mode: 'boolean' }).notNull().default(false),
  isVMI: integer('is_vmi', { mode: 'boolean' }).notNull().default(false),
  leadTimeDays: integer('lead_time_days'),
  paymentTerms: text('payment_terms'),
  isActive: integer('is_active', { mode: 'boolean' }).notNull().default(true),
  createdAt: text('created_at').notNull().default('CURRENT_TIMESTAMP'),
  updatedAt: text('updated_at').notNull().default('CURRENT_TIMESTAMP'),
});

// Approved Vendor List (AVL)
export const sqliteApprovedVendorList = sqliteTable('approved_vendor_list', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  itemId: integer('item_id').notNull().references(() => sqliteItems.id),
  vendorId: integer('vendor_id').notNull().references(() => sqliteVendors.id),
  approvalDate: text('approval_date'),
  expiryDate: text('expiry_date'),
  isPreferred: integer('is_preferred', { mode: 'boolean' }).notNull().default(false),
  createdAt: text('created_at').notNull().default('CURRENT_TIMESTAMP'),
});

// Warehouses (คลังสินค้า)
export const sqliteWarehouses = sqliteTable('warehouses', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  code: text('code').notNull().unique(),
  name: text('name').notNull(),
  type: text('type').notNull(), // raw_material, finished_goods, quarantine, rejected
  location: text('location'),
  capacity: real('capacity'), // Storage capacity in units
  temperatureMin: real('temperature_min'),
  temperatureMax: real('temperature_max'),
  humidityMin: real('humidity_min'),
  humidityMax: real('humidity_max'),
  isActive: integer('is_active', { mode: 'boolean' }).notNull().default(true),
  createdAt: text('created_at').notNull().default('CURRENT_TIMESTAMP'),
  updatedAt: text('updated_at').notNull().default('CURRENT_TIMESTAMP'),
});

// Warehouse Locations/Bins
export const sqliteWarehouseLocations = sqliteTable('warehouse_locations', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  warehouseId: integer('warehouse_id').notNull().references(() => sqliteWarehouses.id),
  code: text('code').notNull(),
  name: text('name'),
  zone: text('zone'),
  rack: text('rack'),
  shelf: text('shelf'),
  bin: text('bin'),
  isActive: integer('is_active', { mode: 'boolean' }).notNull().default(true),
  createdAt: text('created_at').notNull().default('CURRENT_TIMESTAMP'),
});

// Storage Environmental Monitoring Logs (Audit Q6)
// Periodic temp/humidity readings for warehouse storage areas — separate
// from production-area `wo_environmental_logs`. Alerts fire when a reading
// falls outside the warehouse's temperatureMin/Max or humidityMin/Max.
export const sqliteStorageEnvLogs = sqliteTable('storage_env_logs', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  warehouseId: integer('warehouse_id').notNull().references(() => sqliteWarehouses.id),
  locationId: integer('location_id').references(() => sqliteWarehouseLocations.id),
  readingAt: text('reading_at').notNull(),
  temperature: real('temperature'),
  humidity: real('humidity'),
  // 'in_spec' | 'temp_low' | 'temp_high' | 'humidity_low' | 'humidity_high' | 'multiple'
  alertLevel: text('alert_level').notNull().default('in_spec'),
  alertMessage: text('alert_message'),
  acknowledgedBy: integer('acknowledged_by').references(() => sqliteUsers.id),
  acknowledgedAt: text('acknowledged_at'),
  acknowledgedNotes: text('acknowledged_notes'),
  recordedBy: integer('recorded_by').notNull().references(() => sqliteUsers.id),
  notes: text('notes'),
  createdAt: text('created_at').notNull().default('CURRENT_TIMESTAMP'),
});

// Inventory Lots
// QC Inspection (Audit Q5)
// QA-side inspection record. Independent of production BOM — QC department
// fills it out on their own checklist. Can link to a Work Order to expose
// the eBMR for cross-reference, but the form itself is not driven by the BOM.
export const sqliteQcInspections = sqliteTable('qc_inspections', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  inspectionNumber: text('inspection_number').notNull().unique(),
  // Optional link to a WO so the inspector can open its eBMR. Null = ad-hoc.
  workOrderId: integer('work_order_id'),
  // Free-text batch identifier (sometimes QC inspects something with no WO).
  batchNumber: text('batch_number'),
  inspectionType: text('inspection_type').notNull(), // incoming | in_process | finished | ad_hoc
  subject: text('subject').notNull(),
  findings: text('findings'),
  overallResult: text('overall_result').notNull().default('pending'), // pending | pass | fail
  inspectorId: integer('inspector_id').notNull().references(() => sqliteUsers.id),
  inspectedAt: text('inspected_at').notNull(),
  notes: text('notes'),
  createdAt: text('created_at').notNull().default('CURRENT_TIMESTAMP'),
  updatedAt: text('updated_at').notNull().default('CURRENT_TIMESTAMP'),
});

export const sqliteInventoryLots = sqliteTable('inventory_lots', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  itemId: integer('item_id').notNull().references(() => sqliteItems.id),
  lotNumber: text('lot_number').notNull(),
  batchNumber: text('batch_number'),
  warehouseId: integer('warehouse_id').notNull().references(() => sqliteWarehouses.id),
  locationId: integer('location_id').references(() => sqliteWarehouseLocations.id),
  quantity: real('quantity').notNull().default(0),
  reservedQuantity: real('reserved_quantity').notNull().default(0),
  unit: text('unit').notNull(),
  status: text('status').notNull().default('quarantine'), // quarantine, under_test, released, rejected, blocked
  manufacturingDate: text('manufacturing_date'),
  expiryDate: text('expiry_date'),
  receivedDate: text('received_date'),
  vendorId: integer('vendor_id').references(() => sqliteVendors.id),
  vendorLotNumber: text('vendor_lot_number'),
  cost: real('cost'),
  poNumber: text('po_number'),
  coaNumber: text('coa_number'),
  // Phase 2: Manufacturer/Importer fields (FR-055)
  manufacturerName: text('manufacturer_name'),
  manufacturerId: integer('manufacturer_id').references(() => sqliteVendors.id),
  importerName: text('importer_name'),
  importerId: integer('importer_id').references(() => sqliteVendors.id),
  countryOfOrigin: text('country_of_origin'),
  // Phase 2: Retest tracking fields (FR-056)
  retestDate: text('retest_date'),
  retestIntervalMonths: integer('retest_interval_months'),
  lastRetestDate: text('last_retest_date'),
  retestStatus: text('retest_status'), // not_required, pending, scheduled, completed, overdue
  // Material Return module: link a returned lot back to its source lot (self-reference)
  parentLotId: integer('parent_lot_id').references((): AnySQLiteColumn => sqliteInventoryLots.id),
  // Feature 020: source GRN line (additive — nullable, historical lots stay NULL)
  sourceGrnLineId: integer('source_grn_line_id'),
  // QC Flow item 6: two-step release — QC disposition (quality) then warehouse
  // physical count before the lot becomes 'released' / usable.
  qcDisposition: text('qc_disposition'), // null | approved | rejected
  qcDispositionBy: integer('qc_disposition_by').references(() => sqliteUsers.id),
  qcDispositionAt: text('qc_disposition_at'),
  qcDispositionReason: text('qc_disposition_reason'),
  countedQuantity: real('counted_quantity'),
  countedBy: integer('counted_by').references(() => sqliteUsers.id),
  countedAt: text('counted_at'),
  countVarianceReason: text('count_variance_reason'),
  createdAt: text('created_at').notNull().default('CURRENT_TIMESTAMP'),
  updatedAt: text('updated_at').notNull().default('CURRENT_TIMESTAMP'),
});

// Inventory Transactions
export const sqliteInventoryTransactions = sqliteTable('inventory_transactions', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  lotId: integer('lot_id').notNull().references(() => sqliteInventoryLots.id),
  transactionType: text('transaction_type').notNull(), // receive, issue, return, adjust, transfer, scrap, qc_sample, retain_sample
  quantity: real('quantity').notNull(),
  unit: text('unit').notNull(),
  referenceType: text('reference_type'), // PO, WO, SO, ADJUST
  referenceId: integer('reference_id'),
  referenceNumber: text('reference_number'),
  fromWarehouseId: integer('from_warehouse_id').references(() => sqliteWarehouses.id),
  toWarehouseId: integer('to_warehouse_id').references(() => sqliteWarehouses.id),
  reason: text('reason'),
  performedBy: integer('performed_by').references(() => sqliteUsers.id),
  approvedBy: integer('approved_by').references(() => sqliteUsers.id),
  balanceAfter: real('balance_after'), // lot balance snapshot after this transaction
  itemBalanceAfter: real('item_balance_after'), // item total balance snapshot after this transaction
  createdAt: text('created_at').notNull().default('CURRENT_TIMESTAMP'),
});

// Bill of Materials (BOM) / Recipe
export const sqliteBOM = sqliteTable('bom', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  code: text('code').notNull().unique(),
  name: text('name').notNull(),
  productId: integer('product_id').notNull().references(() => sqliteItems.id),
  version: text('version').notNull().default('1.0'),
  status: text('status').notNull().default('draft'), // draft, approved, obsolete
  batchSize: real('batch_size').notNull(),
  batchUnit: text('batch_unit').notNull(),
  yieldTarget: real('yield_target'), // percentage
  lossAllowance: real('loss_allowance'), // percentage
  theoreticalYield: real('theoretical_yield'), // absolute quantity in product unit
  // Fill weight per sub-unit (capsule/tablet) in mg. Used by bulk yield
  // workflow: actual bulk weight ÷ fillWeightMg = capsule count.
  fillWeightMg: real('fill_weight_mg'),
  effectiveDate: text('effective_date'),
  expiryDate: text('expiry_date'),
  approvedBy: integer('approved_by').references(() => sqliteUsers.id),
  approvedAt: text('approved_at'),
  createdAt: text('created_at').notNull().default('CURRENT_TIMESTAMP'),
  updatedAt: text('updated_at').notNull().default('CURRENT_TIMESTAMP'),
});

// BOM Lines
export const sqliteBOMLines = sqliteTable('bom_lines', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  bomId: integer('bom_id').notNull().references(() => sqliteBOM.id),
  itemId: integer('item_id').notNull().references(() => sqliteItems.id),
  quantity: real('quantity').notNull(),
  unit: text('unit').notNull(),
  sequence: integer('sequence').notNull().default(1),
  isOptional: integer('is_optional', { mode: 'boolean' }).notNull().default(false),
  notes: text('notes'),
  // BOM Line Confidentiality fields (014-unit-cost)
  isConfidential: integer('is_confidential', { mode: 'boolean' }),
  confidentialityOverride: text('confidentiality_override').$type<'inherit' | 'public' | 'confidential'>().notNull().default('inherit'),
  // Phase 2: BOM verification columns (FR-063)
  percentageInFormula: real('percentage_in_formula'),
  weighedQty: real('weighed_qty'),
  weighedBy: integer('weighed_by').references(() => sqliteUsers.id),
  verifiedBy: integer('verified_by').references(() => sqliteUsers.id),
  verifiedAt: text('verified_at'),
  createdAt: text('created_at').notNull().default('CURRENT_TIMESTAMP'),
});

// Production Operations/Routing
export const sqliteOperations = sqliteTable('operations', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  bomId: integer('bom_id').notNull().references(() => sqliteBOM.id),
  sequence: integer('sequence').notNull(),
  name: text('name').notNull(),
  description: text('description'),
  workCenterId: integer('work_center_id'),
  standardTime: real('standard_time'), // minutes
  setupTime: real('setup_time'), // minutes
  cleaningTime: real('cleaning_time'), // minutes
  instructions: text('instructions'),
  createdAt: text('created_at').notNull().default('CURRENT_TIMESTAMP'),
});

// Work Orders (ใบสั่งผลิต)
export const sqliteWorkOrders = sqliteTable('work_orders', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  woNumber: text('wo_number').notNull().unique(),
  bomId: integer('bom_id').notNull().references(() => sqliteBOM.id),
  productId: integer('product_id').notNull().references(() => sqliteItems.id),
  batchNumber: text('batch_number').notNull(),
  plannedQuantity: real('planned_quantity').notNull(),
  actualQuantity: real('actual_quantity'),
  rejectQuantity: real('reject_quantity'),
  unit: text('unit').notNull(),
  status: text('status').notNull().default('planned'), // planned, released, in_progress, completed, cancelled
  priority: integer('priority').notNull().default(5),
  plannedStartDate: text('planned_start_date'),
  plannedEndDate: text('planned_end_date'),
  actualStartDate: text('actual_start_date'),
  actualEndDate: text('actual_end_date'),
  deliveryDate: text('delivery_date'),
  yieldPercentage: real('yield_percentage'),
  notes: text('notes'),
  createdBy: integer('created_by').references(() => sqliteUsers.id),
  approvedBy: integer('approved_by').references(() => sqliteUsers.id),
  // Phase 2: Line clearance columns (FR-062)
  lineClearanceRequired: integer('line_clearance_required', { mode: 'boolean' }).notNull().default(true),
  lineClearanceStatus: text('line_clearance_status'), // pending, cleared, failed
  lineClearanceBy: integer('line_clearance_by').references(() => sqliteUsers.id),
  lineClearanceAt: text('line_clearance_at'),
  lineClearanceChecklistId: integer('line_clearance_checklist_id'), // FK added after table creation
  // Material requisition gate
  requisitionStatus: text('requisition_status').notNull().default('none'), // none, requested, approved
  requisitionRequestedBy: integer('requisition_requested_by').references(() => sqliteUsers.id),
  requisitionRequestedAt: text('requisition_requested_at'),
  requisitionApprovedBy: integer('requisition_approved_by').references(() => sqliteUsers.id),
  requisitionApprovedAt: text('requisition_approved_at'),
  // eBMR Approval Signatures — "Produced By" (captured on status → completed transition)
  completedBy: integer('completed_by').references(() => sqliteUsers.id),
  completedAt: text('completed_at'),
  // Bulk Product Yield — recorded after Post-Production, before Packaging
  bulkOutputQty: real('bulk_output_qty'),
  bulkOutputRecordedAt: text('bulk_output_recorded_at'),
  bulkOutputRecordedBy: integer('bulk_output_recorded_by').references(() => sqliteUsers.id),
  // Finished Production Output/Yield — recorded after Inspection, creates FG lot
  finishedOutputQty: real('finished_output_qty'),
  finishedOutputRecordedAt: text('finished_output_recorded_at'),
  finishedOutputRecordedBy: integer('finished_output_recorded_by').references(() => sqliteUsers.id),
  // eBMR Approval Signature — "Approved By (QA)" final QA disposition on the batch.
  // (eBMR audit gap #6 — previously the eBMR rendered an empty QA signature row.)
  qaApprovedBy: integer('qa_approved_by').references(() => sqliteUsers.id),
  qaApprovedAt: text('qa_approved_at'),
  qaApprovalNotes: text('qa_approval_notes'),
  createdAt: text('created_at').notNull().default('CURRENT_TIMESTAMP'),
  updatedAt: text('updated_at').notNull().default('CURRENT_TIMESTAMP'),
});

// Work Order Materials (วัตถุดิบที่ใช้ในใบสั่งผลิต)
export const sqliteWorkOrderMaterials = sqliteTable('work_order_materials', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  workOrderId: integer('work_order_id').notNull().references(() => sqliteWorkOrders.id),
  itemId: integer('item_id').notNull().references(() => sqliteItems.id),
  lotId: integer('lot_id').references(() => sqliteInventoryLots.id),
  plannedQuantity: real('planned_quantity').notNull(),
  actualQuantity: real('actual_quantity'),
  unit: text('unit').notNull(),
  status: text('status').notNull().default('pending'), // pending, issued, returned
  issuedBy: integer('issued_by').references(() => sqliteUsers.id),
  issuedAt: text('issued_at'),
  // SU actually deducted at requisition approve (for weight-tracked items, = puToIssue × Ratio1).
  // Non-null = stock was already physically released to production; weighing must NOT deduct again.
  issuedQty: real('issued_qty'),
  // Phase 3: Enhanced material weighing fields (BMPR Form)
  bomLineId: integer('bom_line_id').references(() => sqliteBOMLines.id), // Reference to BOM formula
  weighedQty: real('weighed_qty'), // Actual weight recorded
  weighedBy: integer('weighed_by').references(() => sqliteUsers.id), // Operator who weighed
  weighedAt: text('weighed_at'),
  verifiedBy: integer('verified_by').references(() => sqliteUsers.id), // Verifier
  verifiedAt: text('verified_at'),
  // Water-specific fields (for water material)
  waterDate: text('water_date'),
  waterConductivity: real('water_conductivity'), // µS·cm⁻¹
  waterTemperature: real('water_temperature'), // °C
  // Unit Cost Calculation fields (014-unit-cost)
  unitCost: real('unit_cost'), // WAC at time of issue
  totalCost: real('total_cost'), // quantity × unitCost
  costLayerId: integer('cost_layer_id'), // Reference to cost layer (added after schema-unit-cost import)
  stockAtApproval: real('stock_at_approval'), // Stock snapshot when requisition was approved
  // Feature 018: cumulative extra qty deducted via approved material withdrawal requests
  additionalQtyViaWithdrawalRequest: real('additional_qty_via_withdrawal_request').notNull().default(0),
  // Feature 021: scale verification gate
  scaleId: integer('scale_id'), // production_equipment.id used to weigh
  scaleVerificationId: integer('scale_verification_id'), // scale_verifications.id under which weighing was performed
  weighedAfterExpiry: integer('weighed_after_expiry', { mode: 'boolean' }).notNull().default(false),
  createdAt: text('created_at').notNull().default('CURRENT_TIMESTAMP'),
});

// Work Order Assignees — team members planned for a batch (GMP traceability).
// Separate from `*_by` audit fields which log who performed actions after the fact;
// this captures who was assigned before work began. One WO → many assignees, each with a role.
export const sqliteWorkOrderAssignees = sqliteTable('work_order_assignees', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  workOrderId: integer('work_order_id').notNull().references(() => sqliteWorkOrders.id, { onDelete: 'cascade' }),
  employeeId: integer('employee_id').notNull().references(() => sqliteHREmployees.id),
  positionId: integer('position_id').references(() => sqliteHRPositions.id), // Snapshot of position; nullable in case employee has no primary position
  role: text('role').notNull(), // operator | supervisor | qa_verifier | ipc_checker | pharmacist
  notes: text('notes'),
  assignedBy: integer('assigned_by').references(() => sqliteUsers.id),
  assignedAt: text('assigned_at').notNull().default('CURRENT_TIMESTAMP'),
});

// Batch Records (eBMR)
export const sqliteBatchRecords = sqliteTable('batch_records', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  workOrderId: integer('work_order_id').notNull().references(() => sqliteWorkOrders.id),
  operationId: integer('operation_id').notNull().references(() => sqliteOperations.id),
  sequence: integer('sequence').notNull(),
  stepName: text('step_name').notNull(),
  instructions: text('instructions'),
  parameters: text('parameters'), // JSON string
  actualValues: text('actual_values'), // JSON string
  status: text('status').notNull().default('pending'), // pending, in_progress, completed, deviation
  startTime: text('start_time'),
  endTime: text('end_time'),
  performedBy: integer('performed_by').references(() => sqliteUsers.id),
  verifiedBy: integer('verified_by').references(() => sqliteUsers.id),
  verifiedAt: text('verified_at'),
  notes: text('notes'),
  attachments: text('attachments'), // JSON array of file paths
  createdAt: text('created_at').notNull().default('CURRENT_TIMESTAMP'),
  updatedAt: text('updated_at').notNull().default('CURRENT_TIMESTAMP'),
});

// Quality Specifications
export const sqliteQualitySpecs = sqliteTable('quality_specs', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  itemId: integer('item_id').notNull().references(() => sqliteItems.id),
  testName: text('test_name').notNull(),
  testMethod: text('test_method'),
  specification: text('specification'),
  minValue: real('min_value'),
  maxValue: real('max_value'),
  unit: text('unit'),
  isCritical: integer('is_critical', { mode: 'boolean' }).notNull().default(false),
  isActive: integer('is_active', { mode: 'boolean' }).notNull().default(true),
  createdAt: text('created_at').notNull().default('CURRENT_TIMESTAMP'),
  updatedAt: text('updated_at').notNull().default('CURRENT_TIMESTAMP'),
});

// Quality Tests
export const sqliteQualityTests = sqliteTable('quality_tests', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  lotId: integer('lot_id').notNull().references(() => sqliteInventoryLots.id),
  specId: integer('spec_id').references(() => sqliteQualitySpecs.id), // nullable for tests without specs
  // Soft FK to ipc_criteria.id when this row snapshots an IPC criteria (testType='in_process').
  // Nullable for non-IPC tests and for legacy rows created before this column existed.
  ipcCriteriaId: integer('ipc_criteria_id'),
  testType: text('test_type').notNull(), // incoming, in_process, final
  sampleNumber: text('sample_number'),
  sampleSize: integer('sample_size'), // AQL sample size
  testDate: text('test_date'),
  result: text('result'),
  numericResult: real('numeric_result'),
  status: text('status').notNull().default('pending'), // pending, pass, fail, retest
  requestedBy: integer('requested_by').references(() => sqliteUsers.id),
  requestedAt: text('requested_at'),
  testedBy: integer('tested_by').references(() => sqliteUsers.id),
  approvedBy: integer('approved_by').references(() => sqliteUsers.id),
  approvedAt: text('approved_at'),
  notes: text('notes'),
  // Spec snapshot at time of test recording (immutable after recording)
  specMinValue: real('spec_min_value'),
  specMaxValue: real('spec_max_value'),
  specSpecification: text('spec_specification'),
  specUnit: text('spec_unit'),
  criteriaType: text('criteria_type').default('numeric'), // numeric, pass_fail, visual, text, checkbox(legacy) — copied from ipc_criteria at init
  tolerancePercent: real('tolerance_percent').default(0), // sample-failure tolerance
  specTarget: real('spec_target'), // copied from ipc_criteria at init
  specTolerancePercent: real('spec_tolerance_percent').default(0), // Min/Max deviation tolerance
  // Phase 3: Multi-stage acceptance plan snapshot (USP <711>, <905>)
  // JSON array; null = single-stage (uses sampleSize + tolerancePercent above).
  acceptanceStages: text('acceptance_stages'),
  // IPC phase snapshot (in_process tests only): pre_production, production,
  // post_production, packaging — drives per-phase IPC card on Execution Dashboard.
  // Null for incoming/final tests where phase is irrelevant.
  ipcPhase: text('ipc_phase'),
  // Retest tracking (FDA OOS 2006 / PIC/S):
  // retestRound = current round number (1 = first test, 2 = first retest)
  // retestReason = 'justified' | 'unjustified' | null. NULL on round 1.
  retestRound: integer('retest_round').notNull().default(1),
  retestReason: text('retest_reason'),
  // Phase 2: Disposition columns (FR-067 to FR-070)
  disposition: text('disposition'), // pending, accept, reject, rework, scrap, return_to_vendor, conditional_release
  dispositionBy: integer('disposition_by').references(() => sqliteUsers.id),
  dispositionAt: text('disposition_at'),
  dispositionReason: text('disposition_reason'),
  dispositionApprovedBy: integer('disposition_approved_by').references(() => sqliteUsers.id),
  dispositionApprovedAt: text('disposition_approved_at'),
  createdAt: text('created_at').notNull().default('CURRENT_TIMESTAMP'),
  updatedAt: text('updated_at').notNull().default('CURRENT_TIMESTAMP'),
});

