// BOM Room Requirements - Link rooms to BOM for each phase
export const sqliteBOMRooms = sqliteTable('bom_rooms', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  bomId: integer('bom_id').notNull().references(() => sqliteBOM.id),
  roomId: integer('room_id').notNull().references(() => sqliteProductionRooms.id),
  phase: text('phase').notNull(), // pre_production, production, post_production, pre_packaging, packaging
  sequence: integer('sequence').notNull().default(1),
  isRequired: integer('is_required', { mode: 'boolean' }).notNull().default(true),
  createdAt: text('created_at').notNull().default('CURRENT_TIMESTAMP'),
});

// BOM Equipment Requirements - Link equipment to BOM for each phase
export const sqliteBOMEquipment = sqliteTable('bom_equipment', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  bomId: integer('bom_id').notNull().references(() => sqliteBOM.id),
  equipmentId: integer('equipment_id').notNull().references(() => sqliteProductionEquipment.id),
  phase: text('phase').notNull(), // pre_production, production, post_production, pre_packaging, packaging
  sequence: integer('sequence').notNull().default(1),
  isRequired: integer('is_required', { mode: 'boolean' }).notNull().default(true),
  createdAt: text('created_at').notNull().default('CURRENT_TIMESTAMP'),
});

// BOM Environmental Conditions - Link environmental conditions to BOM phases
export const sqliteBOMEnvironmentalConditions = sqliteTable('bom_environmental_conditions', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  bomId: integer('bom_id').notNull().references(() => sqliteBOM.id),
  conditionId: integer('condition_id').notNull().references(() => sqliteEnvironmentalConditions.id),
  bomRoomId: integer('bom_room_id').references(() => sqliteBOMRooms.id),
  phase: text('phase').notNull(), // pre_production, production, packaging
  createdAt: text('created_at').notNull().default('CURRENT_TIMESTAMP'),
}, (table) => [
  sqliteUniqueIndex('uq_bom_phase_condition').on(table.bomId, table.phase, table.conditionId),
]);

// BOM SOP Steps - Detailed SOP steps for BOM with parameters
export const sqliteBOMSOPSteps = sqliteTable('bom_sop_steps', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  bomId: integer('bom_id').notNull().references(() => sqliteBOM.id),
  templateId: integer('template_id').references(() => sqliteSOPStepTemplates.id),
  sequence: integer('sequence').notNull(),
  stepName: text('step_name').notNull(),
  stepNameTh: text('step_name_th'),
  instructions: text('instructions'),
  instructionsTh: text('instructions_th'),
  // Step-specific parameters (override template defaults)
  parameters: text('parameters'), // JSON: { temperature: 75, mixingSpeed: 45, duration: 5 }
  // Required equipment for this step
  equipmentIds: text('equipment_ids'), // JSON array of equipment IDs
  // Verification requirements
  requiresVerification: integer('requires_verification', { mode: 'boolean' }).notNull().default(true),
  // Audit #16 — critical steps require Production Manager approval
  // on top of operator + verifier.
  isCritical: integer('is_critical', { mode: 'boolean' }).notNull().default(false),
  // Phase determines which Execution Dashboard card hosts this step.
  // Values: pre_production, production, post_production, packaging
  phase: text('phase').notNull().default('production'),
  createdAt: text('created_at').notNull().default('CURRENT_TIMESTAMP'),
});

// BOM Packaging QC - Link packaging QC criteria to BOM
export const sqliteBOMPackagingQC = sqliteTable('bom_packaging_qc', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  bomId: integer('bom_id').notNull().references(() => sqliteBOM.id),
  criteriaId: integer('criteria_id').notNull().references(() => sqlitePackagingQCCriteria.id),
  createdAt: text('created_at').notNull().default('CURRENT_TIMESTAMP'),
});

// BOM SOP-Step IPC Links — replaces master sop_template_ipc_criteria.
// Each BOM owns its own IPC linkages per SOP step (and optionally per
// sub-step via procedureStepId). Allows different BOMs to attach different
// IPC criteria to the same SOP template step.
export const sqliteBOMSOPStepIPC = sqliteTable('bom_sop_step_ipc', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  bomStepId: integer('bom_step_id').notNull().references(() => sqliteBOMSOPSteps.id),
  // Sub-step within the SOP template (nullable = whole BOM step).
  procedureStepId: integer('procedure_step_id').references(() => sqliteSOPTemplateSteps.id),
  criteriaId: integer('criteria_id').notNull().references(() => sqliteIPCCriteria.id),
  sequence: integer('sequence').notNull().default(1),
  sampleSize: integer('sample_size').notNull().default(1),
  isCritical: integer('is_critical', { mode: 'boolean' }).notNull().default(false),
  // BOM-level override of master ipc_criteria.maxRetestRounds.
  // NULL = inherit from master criterion.
  maxRetestRounds: integer('max_retest_rounds'),
  notes: text('notes'),
  createdAt: text('created_at').notNull().default('CURRENT_TIMESTAMP'),
});

// BOM In-Process QC - Link quality specs to BOM for IPC tests
// IPC Criteria (Master Data) - In-Process Control test criteria templates
export const sqliteIPCCriteria = sqliteTable('ipc_criteria', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  code: text('code').notNull().unique(),
  name: text('name').notNull(),
  nameTh: text('name_th'),
  testMethod: text('test_method'),
  specification: text('specification'), // e.g., "200 ± 10 mg"
  minValue: real('min_value'),
  maxValue: real('max_value'),
  unit: text('unit'), // e.g., "mg", "mm", "min"
  sampleSize: integer('sample_size').notNull().default(5),
  checkIntervalMinutes: integer('check_interval_minutes').notNull().default(30),
  isCritical: integer('is_critical', { mode: 'boolean' }).notNull().default(false),
  isActive: integer('is_active', { mode: 'boolean' }).notNull().default(true),
  dosageForm: text('dosage_form'),
  criteriaType: text('criteria_type').notNull().default('numeric'), // numeric, pass_fail, visual, text, multi_point, tare (legacy: checkbox)
  // Soft reference to another ipc_criteria.id (criteriaType='tare').
  // Used by multi_point recording to auto-subtract Gross − Tare. No FK
  // constraint — referenced criteria may be archived independently.
  tareSourceCriteriaId: integer('tare_source_criteria_id'),
  tolerancePercent: real('tolerance_percent').notNull().default(0), // sample-failure tolerance %
  // Target-based spec (pharmacy/chemistry concept: "300 ± 5%")
  // When specTarget is set, minValue/maxValue are derived from it at save time
  specTarget: real('spec_target'),
  specTolerancePercent: real('spec_tolerance_percent').notNull().default(0),
  // Multi-stage acceptance plan (USP <711>, <905>) — JSON array of stages.
  // Empty/null = single-stage (uses sampleSize + tolerancePercent above).
  // Each stage: { sampleSize, tolerancePercent, onFail: 'next_stage'|'reject_batch'|'deviation' }
  acceptanceStages: text('acceptance_stages'),
  // Max retest rounds before forcing deviation (FDA OOS 2006 / PIC/S).
  // Default = 1 (allow 1 retest = max 2 rounds total).
  // Critical criteria force this to 0 at runtime (deviation immediately on round 1 fail).
  maxRetestRounds: integer('max_retest_rounds').notNull().default(1),
  // Optional link to a controlled GMP document (e.g. test method SOP).
  // Soft reference to documents.id — no FK so the document can be archived
  // independently. Shown + previewable on the work-order IPC recording screen.
  gmpDocumentId: integer('gmp_document_id'),
  createdAt: text('created_at').notNull().default('CURRENT_TIMESTAMP'),
});

// IPC Recording Rounds — criteria-centric immutable submission log.
// Replaces the WO-coupled quality_tests path. One row per (criteria, batch, round).
// Submitted rounds are read-only — multi-round support comes from inserting
// additional rows with incremented roundNumber.
export const sqliteIPCRecordingRounds = sqliteTable('ipc_recording_rounds', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  criteriaId: integer('criteria_id').notNull().references(() => sqliteIPCCriteria.id),
  // Batch identifier — string to allow non-WO contexts (cleaning verify, equipment qual).
  // Empty string = "ad-hoc" recording not tied to a batch.
  batchNumber: text('batch_number').notNull().default(''),
  // Round index within (criteriaId, batchNumber). Starts at 1 — incremented when
  // operator clicks "+ บันทึกรอบใหม่" after a fail.
  roundNumber: integer('round_number').notNull().default(1),
  reason: text('reason'), // e.g. "หลังปรับ tamping pin"
  // Round payload — JSON shape varies by criteriaType:
  //   numeric/tare:  { value: '12.3' }
  //   pass_fail:     { value: 'pass' | 'fail' }
  //   visual:        { checks: { 0: true, 1: false, ... } }
  //   text:          { value: '...' }
  //   multi_point:   { points: ['0.5', '0.49', ...] }
  data: text('data').notNull().default('{}'),
  startedAt: text('started_at').notNull().default('CURRENT_TIMESTAMP'),
  startedById: integer('started_by_id').notNull().references(() => sqliteUsers.id),
  // Submit info — locked once set (immutable from API layer).
  submittedAt: text('submitted_at'),
  submittedById: integer('submitted_by_id').references(() => sqliteUsers.id),
  // Pinned to specific criteria revision at submit time (NULL until versioning ships).
  criteriaVersionId: integer('criteria_version_id'),
  // Server-side computed at submit.
  passed: integer('passed', { mode: 'boolean' }),
  computedMean: real('computed_mean'),
  outcomeNote: text('outcome_note'),
  // Triple Independence — a second qualified person (≠ submittedById) verifies
  // the locked round. NULL until verified. Gates the GMP sign-off the same way
  // legacy IPC approval does. Independence is enforced in the verify API.
  verifiedAt: text('verified_at'),
  verifiedById: integer('verified_by_id').references(() => sqliteUsers.id),
});

export const sqliteBOMInProcessQC = sqliteTable('bom_in_process_qc', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  bomId: integer('bom_id').notNull().references(() => sqliteBOM.id),
  criteriaId: integer('criteria_id').notNull().references(() => sqliteIPCCriteria.id),
  sequence: integer('sequence').notNull().default(1),
  sampleSize: integer('sample_size').notNull().default(1),
  isCritical: integer('is_critical', { mode: 'boolean' }).notNull().default(false),
  // Phase determines which Execution Dashboard card hosts this IPC test.
  // Values: pre_production, production, post_production, packaging
  phase: text('phase').notNull().default('production'),
  // Override of master ipc_criteria.max_retest_rounds for this BOM.
  // NULL = inherit from master.
  maxRetestRounds: integer('max_retest_rounds'),
  createdAt: text('created_at').notNull().default('CURRENT_TIMESTAMP'),
});

