// Work Order Packaging Materials - Packaging material consumption
export const sqliteWOPackagingMaterials = sqliteTable('wo_packaging_materials', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  workOrderId: integer('work_order_id').notNull().references(() => sqliteWorkOrders.id),
  itemId: integer('item_id').references(() => sqliteItems.id), // Reference to inventory item
  materialName: text('material_name').notNull(),
  qtyRequisitioned: real('qty_requisitioned').notNull(),
  qtyUsed: real('qty_used'),
  qtyReturned: real('qty_returned'),
  unit: text('unit').notNull(),
  operatorId: integer('operator_id').references(() => sqliteUsers.id),
  verifierId: integer('verifier_id').references(() => sqliteUsers.id),
  // Feature 019: Primary Packaging Issuance flow columns (nullable for backward compat with existing rows)
  sourceLotId: integer('source_lot_id'),
  containerLabel: text('container_label'),
  verifierUserId: integer('verifier_user_id'),
  verifierSignatureId: integer('verifier_signature_id'),
  verifiedAt: text('verified_at'),
  // pending_verification | issued | cancelled — distinct from legacy unused 'status'
  flowStatus: text('flow_status').default('pending_verification'),
  roomId: integer('room_id'),
  createdAt: text('created_at').notNull().default('CURRENT_TIMESTAMP'),
  updatedAt: text('updated_at').notNull().default('CURRENT_TIMESTAMP'),
});

// ============================================
// MySQL Schema (for production)
// ============================================

// Users table
export const mysqlUsers = mysqlTable('users', {
  id: int('id').primaryKey().autoincrement(),
  email: varchar('email', { length: 255 }).notNull().unique(),
  password: varchar('password', { length: 255 }).notNull(),
  name: varchar('name', { length: 255 }).notNull(),
  role: varchar('role', { length: 50 }).notNull().default('user'),
  department: varchar('department', { length: 100 }),
  isActive: mysqlBoolean('is_active').notNull().default(true),
  createdAt: datetime('created_at').notNull().default(sql`CURRENT_TIMESTAMP`),
  updatedAt: datetime('updated_at').notNull().default(sql`CURRENT_TIMESTAMP`),
});

// Audit Trail
export const mysqlAuditTrail = mysqlTable('audit_trail', {
  id: int('id').primaryKey().autoincrement(),
  userId: int('user_id').references(() => mysqlUsers.id),
  action: varchar('action', { length: 50 }).notNull(),
  tableName: varchar('table_name', { length: 100 }),
  recordId: int('record_id'),
  oldValue: mysqlText('old_value'),
  newValue: mysqlText('new_value'),
  ipAddress: varchar('ip_address', { length: 50 }),
  createdAt: datetime('created_at').notNull().default(sql`CURRENT_TIMESTAMP`),
});

// Item Categories (หมวดหมู่สินค้า)
export const mysqlItemCategories = mysqlTable('item_categories', {
  id: int('id').primaryKey().autoincrement(),
  code: varchar('code', { length: 50 }).notNull().unique(),
  nameTh: varchar('name_th', { length: 255 }).notNull(),
  nameEn: varchar('name_en', { length: 255 }),
  description: varchar('description', { length: 500 }),
  sortOrder: int('sort_order').notNull().default(0),
  isActive: mysqlBoolean('is_active').notNull().default(true),
  createdAt: datetime('created_at').notNull().default(sql`CURRENT_TIMESTAMP`),
  updatedAt: datetime('updated_at').notNull().default(sql`CURRENT_TIMESTAMP`),
});

// Lot Number Patterns — MySQL twin of sqliteLotPatterns.
export const mysqlLotPatterns = mysqlTable('lot_patterns', {
  id: int('id').primaryKey().autoincrement(),
  patternType: varchar('pattern_type', { length: 20 }).notNull().unique(),
  prefix: varchar('prefix', { length: 20 }).notNull().default('LOT'),
  separator: varchar('separator', { length: 5 }).notNull().default('-'),
  includeDate: mysqlBoolean('include_date').notNull().default(true),
  dateFormat: varchar('date_format', { length: 20 }).notNull().default('YYYYMMDD'),
  sequenceType: varchar('sequence_type', { length: 20 }).notNull().default('random'),
  sequenceLength: int('sequence_length').notNull().default(3),
  sequenceStart: int('sequence_start').notNull().default(1),
  regexPattern: varchar('regex_pattern', { length: 200 }),
  hintTh: varchar('hint_th', { length: 200 }),
  hintEn: varchar('hint_en', { length: 200 }),
  isActive: mysqlBoolean('is_active').notNull().default(true),
  notes: mysqlText('notes'),
  updatedBy: int('updated_by').references(() => mysqlUsers.id),
  createdAt: datetime('created_at').notNull().default(sql`CURRENT_TIMESTAMP`),
  updatedAt: datetime('updated_at').notNull().default(sql`CURRENT_TIMESTAMP`),
});

// Item Code Patterns — MySQL twin of sqliteItemCodePatterns.
export const mysqlItemCodePatterns = mysqlTable('item_code_patterns', {
  id: int('id').primaryKey().autoincrement(),
  itemType: varchar('item_type', { length: 30 }).notNull().unique(),
  prefix: varchar('prefix', { length: 20 }).notNull(),
  separator: varchar('separator', { length: 5 }).notNull().default('-'),
  padding: int('padding').notNull().default(4),
  includeYear: mysqlBoolean('include_year').notNull().default(false),
  yearFormat: varchar('year_format', { length: 10 }).notNull().default('YYYY'),
  yearPosition: varchar('year_position', { length: 20 }).notNull().default('after_prefix'),
  sequenceStart: int('sequence_start').notNull().default(1),
  isActive: mysqlBoolean('is_active').notNull().default(true),
  notes: mysqlText('notes'),
  updatedBy: int('updated_by').references(() => mysqlUsers.id),
  createdAt: datetime('created_at').notNull().default(sql`CURRENT_TIMESTAMP`),
  updatedAt: datetime('updated_at').notNull().default(sql`CURRENT_TIMESTAMP`),
});

// Item Units (หน่วยวัดสินค้า)
export const mysqlItemUnits = mysqlTable('item_units', {
  id: int('id').primaryKey().autoincrement(),
  code: varchar('code', { length: 50 }).notNull().unique(),
  nameTh: varchar('name_th', { length: 255 }).notNull(),
  nameEn: varchar('name_en', { length: 255 }),
  symbol: varchar('symbol', { length: 20 }), // e.g., kg, g, L, pcs
  description: varchar('description', { length: 500 }),
  sortOrder: int('sort_order').notNull().default(0),
  isActive: mysqlBoolean('is_active').notNull().default(true),
  createdAt: datetime('created_at').notNull().default(sql`CURRENT_TIMESTAMP`),
  updatedAt: datetime('updated_at').notNull().default(sql`CURRENT_TIMESTAMP`),
});

// Item Master
export const mysqlItems = mysqlTable('items', {
  id: int('id').primaryKey().autoincrement(),
  code: varchar('code', { length: 50 }).notNull().unique(),
  nameTh: varchar('name_th', { length: 255 }).notNull(),
  nameEn: varchar('name_en', { length: 255 }),
  type: varchar('type', { length: 50 }).notNull(),
  category: varchar('category', { length: 100 }),
  primaryUnit: varchar('primary_unit', { length: 50 }).notNull(),
  secondaryUnit: varchar('secondary_unit', { length: 50 }),
  conversionRate: decimal('conversion_rate', { precision: 10, scale: 4 }),
  // 3-level unit conversion (PU → SU → WU)
  weightUnit: varchar('weight_unit', { length: 50 }), // WU label e.g. 'g'
  secondaryToWeightRate: decimal('secondary_to_weight_rate', { precision: 10, scale: 4 }), // Ratio2: 1 SU = ? WU
  weightTrackingEnabled: mysqlBoolean('weight_tracking_enabled').notNull().default(false),
  shelfLifeDays: int('shelf_life_days'),
  storageCondition: varchar('storage_condition', { length: 255 }),
  minStock: decimal('min_stock', { precision: 15, scale: 4 }).default('0'),
  maxStock: decimal('max_stock', { precision: 15, scale: 4 }),
  reorderPoint: decimal('reorder_point', { precision: 15, scale: 4 }),
  onHand: decimal('on_hand', { precision: 15, scale: 4 }).notNull().default('0'), // Cached on-hand quantity from released lots
  onHandCost: decimal('on_hand_cost', { precision: 15, scale: 4 }).notNull().default('0'), // Cached total cost of on-hand inventory
  quarantineQty: decimal('quarantine_qty', { precision: 15, scale: 4 }).notNull().default('0'), // Cached quantity in quarantine/under_test status
  isLotControlled: mysqlBoolean('is_lot_controlled').notNull().default(true),
  isFEFO: mysqlBoolean('is_fefo').notNull().default(true),
  isActive: mysqlBoolean('is_active').notNull().default(true),
  // BOM Confidentiality Protection fields (014-unit-cost)
  confidentialityLevel: mysqlEnum('confidentiality_level', ['public', 'internal', 'confidential']).notNull().default('public'),
  defaultConfidential: mysqlBoolean('default_confidential').notNull().default(false),
  // VMI Standard Codes - items need EITHER tppCode OR ttmtCode for VMI sync
  tppCode: varchar('tpp_code', { length: 13 }), // Thai Pharmaceutical Product code (13 digits)
  tppName: varchar('tpp_name', { length: 255 }), // TPP product name from VMI Portal
  ttmtCode: varchar('ttmt_code', { length: 10 }), // Thai Traditional Medicine Terminology (A + 8 digits)
  ttmtName: varchar('ttmt_name', { length: 255 }), // TTMT product name (FSN) from VMI Portal
  drugCode24: varchar('drug_code_24', { length: 24 }), // 24-digit drug registration code
  // VMI Vendor Sync fields (008-vmi-vendor-sync)
  vmiSyncEnabled: mysqlBoolean('vmi_sync_enabled').notNull().default(false),
  lastVmiSyncAt: datetime('last_vmi_sync_at'),
  // Phase 2: Strength/potency for finished goods (FR-059)
  strength: varchar('strength', { length: 100 }), // legacy free-text (back-compat / display)
  // Structured strength so BOM + WO can compute (value + selectable unit).
  strengthValue: decimal('strength_value', { precision: 15, scale: 4 }),
  strengthUnit: varchar('strength_unit', { length: 30 }),
  // Net weight of ONE sub-unit in mg (e.g. an empty capsule shell). Used by the
  // WO yield step: powder weight + capsuleCount × unitWeightMg = filled weight.
  unitWeightMg: decimal('unit_weight_mg', { precision: 15, scale: 4 }),
  gRegNumber: varchar('g_reg_number', { length: 50 }), // เลขที่ทะเบียน G
  // Unit Cost Calculation fields (014-unit-cost)
  currentWAC: decimal('current_wac', { precision: 15, scale: 4 }), // Current weighted average cost
  lastPurchaseCost: decimal('last_purchase_cost', { precision: 15, scale: 4 }), // From most recent PO receipt
  lastPurchaseDate: datetime('last_purchase_date'), // Date of last purchase
  lastPurchasePoId: int('last_purchase_po_id'), // FK to purchase_orders (no Drizzle ref to avoid circular)
  lastProductionCost: decimal('last_production_cost', { precision: 15, scale: 4 }), // From most recent completed WO
  lastProductionDate: datetime('last_production_date'), // Date of last production
  lastProductionWoId: int('last_production_wo_id'), // FK to work_orders (no Drizzle ref to avoid circular)
  sgaAllocationRate: decimal('sga_allocation_rate', { precision: 5, scale: 2 }).default('0'), // SG&A % for full cost
  standardCost: decimal('standard_cost', { precision: 15, scale: 4 }), // Standard cost for variance analysis
  createdAt: datetime('created_at').notNull().default(sql`CURRENT_TIMESTAMP`),
  updatedAt: datetime('updated_at').notNull().default(sql`CURRENT_TIMESTAMP`),
});

