// Sales Order Lines
export const mysqlSalesOrderLines = mysqlTable('sales_order_lines', {
  id: int('id').primaryKey().autoincrement(),
  soId: int('so_id').notNull().references(() => mysqlSalesOrders.id),
  itemId: int('item_id').notNull().references(() => mysqlItems.id),
  lotId: int('lot_id').references(() => mysqlInventoryLots.id),
  quantity: decimal('quantity', { precision: 15, scale: 4 }).notNull(),
  allocatedQuantity: decimal('allocated_quantity', { precision: 15, scale: 4 }).notNull().default('0'),
  shippedQuantity: decimal('shipped_quantity', { precision: 15, scale: 4 }).notNull().default('0'),
  unit: varchar('unit', { length: 50 }).notNull(),
  unitPrice: decimal('unit_price', { precision: 15, scale: 2 }).notNull(),
  totalPrice: decimal('total_price', { precision: 15, scale: 2 }).notNull(),
  notes: mysqlText('notes'),
  // Unit Cost Calculation fields (014-unit-cost)
  unitCost: decimal('unit_cost', { precision: 15, scale: 4 }), // WAC at time of shipment
  totalCost: decimal('total_cost', { precision: 15, scale: 4 }), // quantity × unitCost (COGS)
  marginAmount: decimal('margin_amount', { precision: 15, scale: 4 }), // (unitPrice - unitCost) × qty
  // precision 10 so deep-discount / cost-over-price margins (e.g. -4400%) fit;
  // 5,2 capped at ±999.99 and overflowed ("Out of range value").
  marginPercent: decimal('margin_percent', { precision: 10, scale: 2 }), // margin ÷ revenue × 100
  createdAt: datetime('created_at').notNull().default(sql`CURRENT_TIMESTAMP`),
});

